"use client";

// glitch-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { useEffect, useRef, useState } from "react";
import { useReducedMotion } from "motion/react";
import { Caption, Foot, Plate, ScreenButton } from "./chrome";

/* ---------------------------------- glitch --------------------------------- */

export function GlitchDemo() {
  const [run, setRun] = useState(false);
  const reduce = useReducedMotion();
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );

  function fire() {
    if (reduce) return;
    setRun(false);
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      setRun(true);
      timer.current = setTimeout(() => setRun(false), 460);
    }, 20);
  }

  return (
    <ScreenButton
      onMouseEnter={fire}
      onClick={fire}
      onFocus={fire}
      aria-label="Replay the glitch 404 demo"
    >
      <Plate
        src="/worlds/px1.webp"
        className="opacity-70 transition-opacity duration-500 group-hover:opacity-85"
      />
      <div className="absolute inset-0 bg-[linear-gradient(180deg,rgba(8,9,10,0.3)_0%,rgba(8,9,10,0.62)_45%,rgba(8,9,10,0.94)_100%)]" />
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,rgba(8,9,10,0.55)_0%,transparent_68%)]" />
      <Caption label="404 / glitch" />

      <div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-3 pt-4">
        <div
          className="glitch-digits display text-[76px] leading-none text-fg"
          data-run={run}
        >
          404
          <span aria-hidden>404</span>
          <span aria-hidden>404</span>
        </div>
        <p className="lab-mono text-[10px] text-white/60">
          this path was never built
        </p>
      </div>

      <Foot method="clip-path" />
    </ScreenButton>
  );
}

"use client";

// mosaic-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { motion, useReducedMotion } from "motion/react";
import { Caption, EASE, Foot, Screen, useReplay } from "./chrome";

/* ---------------------------------- mosaic --------------------------------- */

const TILES = Array.from({ length: 12 }, (_, i) => ({
  c: i % 4,
  r: Math.floor(i / 4),
}));

export function MosaicDemo() {
  const reduce = useReducedMotion();
  const { run, replay } = useReplay();

  return (
    <Screen onPointerEnter={replay} onClick={replay}>
      {TILES.map(({ c, r }, i) => (
        <motion.div
          key={`${run}-${i}`}
          className="absolute h-1/3 w-1/4"
          style={{
            left: `${c * 25}%`,
            top: `${r * 33.3333}%`,
            backgroundImage: "url(/worlds/w-dark-ridge.webp)",
            backgroundSize: "400% 300%",
            backgroundPosition: `${c * 33.3333}% ${r * 50}%`,
            boxShadow: "inset 0 0 0 1px rgba(8,9,10,0.85)",
          }}
          initial={reduce ? false : { opacity: 0, scale: 0.78 }}
          whileInView={{ opacity: 1, scale: 1 }}
          viewport={{ once: true }}
          transition={{
            duration: 0.55,
            ease: EASE,
            delay: (Math.abs(c - 1.5) + Math.abs(r - 1)) * 0.06,
          }}
        />
      ))}

      <div className="absolute inset-0 bg-[linear-gradient(180deg,rgba(8,9,10,0.35)_0%,rgba(8,9,10,0.05)_40%,rgba(8,9,10,0.85)_100%)]" />
      <Caption label="404 / mosaic" />

      <div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-2">
        <span className="display text-[68px] leading-none text-fg drop-shadow-[0_2px_14px_rgba(8,9,10,0.7)]">
          404
        </span>
        <span className="lab-mono text-[10px] text-white/75">
          assembled from twelve tiles
        </span>
      </div>

      <Foot method="mosaic · 12 tiles" />
    </Screen>
  );
}

"use client";

// odometer-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { motion, useReducedMotion } from "motion/react";
import { Caption, Foot, Screen, useReplay } from "./chrome";

/* --------------------------------- odometer -------------------------------- */

const CELL = 76;

function reel(target: string, cycles: number) {
  const seq: string[] = [];
  for (let i = 0; i < cycles * 10 + 2; i += 1) seq.push(String(i % 10));
  if (seq[seq.length - 1] !== target) seq.push(target);
  return seq;
}

const REELS = [
  reel("4", 2),
  reel("0", 2),
  reel("4", 1),
];

export function OdometerDemo() {
  const reduce = useReducedMotion();
  const { run, replay } = useReplay();

  return (
    <Screen onPointerEnter={replay} onClick={replay} className="bg-[#07080a]">
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,rgba(242,237,227,0.05),transparent_65%)]" />
      <div className="absolute inset-0 flex flex-col items-center justify-center gap-4">
        <div className="flex items-start gap-1.5">
          {REELS.map((seq, i) => (
            <div
              key={i}
              className="relative h-[76px] w-[56px] overflow-hidden border-y border-line-2 bg-ink-850/60"
              style={{
                maskImage:
                  "linear-gradient(180deg, transparent 0%, #000 18%, #000 82%, transparent 100%)",
                WebkitMaskImage:
                  "linear-gradient(180deg, transparent 0%, #000 18%, #000 82%, transparent 100%)",
              }}
            >
              {reduce ? (
                <span className="grid h-[76px] place-items-center display text-[62px] leading-none text-fg">
                  {seq[seq.length - 1]}
                </span>
              ) : (
                <motion.div
                  key={run}
                  initial={{ y: 0 }}
                  animate={{ y: -(seq.length - 1) * CELL }}
                  transition={{
                    duration: 1.9,
                    delay: i * 0.14,
                    ease: [0.16, 1, 0.3, 1],
                  }}
                >
                  {seq.map((d, j) => (
                    <span
                      key={j}
                      className="grid h-[76px] place-items-center display text-[62px] leading-none tabular-nums text-fg"
                    >
                      {d}
                    </span>
                  ))}
                </motion.div>
              )}
            </div>
          ))}
        </div>
        <p className="lab-mono text-[10px] text-white/50">
          three reels, one answer
        </p>
      </div>

      <div className="absolute inset-x-0 top-[26%] h-px bg-gradient-to-r from-transparent via-line-2 to-transparent" />
      <div className="absolute inset-x-0 bottom-[26%] h-px bg-gradient-to-r from-transparent via-line-2 to-transparent" />

      <Caption label="404 / odometer" />
      <Foot method="reels · 3 digits" />
    </Screen>
  );
}

"use client";

// spotlight-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { useEffect, useRef, useState } from "react";
import { motion, useMotionTemplate, useMotionValue } from "motion/react";
import { Caption, Foot, Plate, Screen } from "./chrome";

/* -------------------------------- spotlight -------------------------------- */

export function SpotlightDemo() {
  const ref = useRef<HTMLDivElement>(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const [ready, setReady] = useState(false);

  const mask = useMotionTemplate`radial-gradient(150px circle at ${x}px ${y}px, #000 25%, transparent 78%)`;

  useEffect(() => {
    const r = ref.current?.getBoundingClientRect();
    if (!r) return;
    x.set(r.width / 2);
    y.set(r.height / 2);
  }, [x, y]);

  function move(e: React.PointerEvent<HTMLDivElement>) {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    x.set(e.clientX - rect.left);
    y.set(e.clientY - rect.top);
    if (!ready) setReady(true);
  }

  function leave() {
    setReady(false);
    const r = ref.current?.getBoundingClientRect();
    if (!r) return;
    x.set(r.width / 2);
    y.set(r.height / 2);
  }

  return (
    <Screen ref={ref} onPointerMove={move} onPointerLeave={leave}>
      <div className="absolute inset-0">
        <Plate src="/worlds/in3.webp" className="brightness-[0.22]" />
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-3">
          <span className="display text-[76px] leading-none text-white/55">
            404
          </span>
          <span className="lab-mono text-[10px] text-white/55">
            nothing here either
          </span>
        </div>
      </div>

      <motion.div
        className="absolute inset-0"
        style={{
          maskImage: mask,
          WebkitMaskImage: mask,
        }}
        animate={{ opacity: ready ? 1 : 0.42 }}
        transition={{ duration: 0.35 }}
      >
        <Plate src="/worlds/in3.webp" className="brightness-100" />
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-3">
          <span className="display text-[76px] leading-none text-fg">404</span>
          <span className="lab-mono text-[10px] text-white/70">
            nothing here either
          </span>
        </div>
      </motion.div>

      <Caption label="404 / spotlight" />
      <Foot method="move to look" />
    </Screen>
  );
}

