  function reset() {
    rx.set(0);
    ry.set(0);
    gx.set(50);
    gy.set(50);
  }

  return (
    <Screen ref={ref} onPointerMove={move} onPointerLeave={reset}>
      <div className="absolute inset-0 [perspective:900px]">
