      <div
        className="absolute left-1/2 top-[47%] w-[88%] -translate-x-1/2 -translate-y-1/2 bg-[#e6ddc6] shadow-[0_14px_40px_rgba(0,0,0,0.55)]"
        style={{ aspectRatio: "88 / 56" }}
