            </p>
          </div>
        </div>

        <div
          className="absolute inset-x-[4.5%] top-[13.5%] h-px"
          style={{ background: "rgba(36,31,24,0.24)" }}
        />

        {/* field */}
        <div
          className="absolute left-1/2 top-[47%] w-[70%] -translate-x-1/2 -translate-y-1/2"
          onPointerLeave={() => setHover(null)}
        >
