        </span>
      </div>

      <div className="pointer-events-none absolute inset-x-0 bottom-[6.5%] flex justify-center">
        <p className="lab-mono text-[7px] tracking-[0.16em] text-[#6c6455]">
          ONE CARD, ONE MISSING PAGE
        </p>
