  const depth = (tide * 2.4 + 0.2).toFixed(1);
  const word =
    tide < 0.22 ? "EBB" : tide < 0.5 ? "FLOOD" : tide < 0.8 ? "HIGH" : "SPRING";
  const chromeInk =
    tide > 0.58 ? "rgba(235,238,224,0.74)" : "rgba(20,32,30,0.68)";
