  --color-ink-800: #232327;
  --color-fg: #fafafa;
  --color-fg-2: #b3b3b9;
  --color-fg-3: #7c7c84;
  --color-line: #26262a;
  --color-line-2: #35353b;
  --color-amber: #e9b871;

  /* One radius scale: panels, media tiles, controls. */
  --radius-panel: 20px;
  --radius-tile: 12px;
  --radius-control: 8px;

  /* Public type tokens. Override these two to reskin the library. */
